import java.io.*;import java.util.*;public class Main {static List<Integer>[] adj;static long[] costs;static boolean[] visited;static long minCost;public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());costs = new long[n + 1];st = new StringTokenizer(br.readLine());for (int i = 1; i <= n; i++) {costs[i] = Long.parseLong(st.nextToken());}adj = new ArrayList[n + 1];for (int i = 1; i <= n; i++) {adj[i] = new ArrayList<>();}for (int i = 0; i < m; i++) {st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj[u].add(v);adj[v].add(u);}visited = new boolean[n + 1];long totalCost = 0;for (int i = 1; i <= n; i++) {if (!visited[i]) {minCost = costs[i];dfs(i);totalCost += minCost;}}System.out.println(totalCost);}private static void dfs(int u) {visited[u] = true;if (costs[u] < minCost) {minCost = costs[u];}for (int v : adj[u]) {if (!visited[v]) {dfs(v);}}}}